// File: p2p-kids-marketplace/src/hooks/usePaymentSheet.ts
// MODULE-11 SUB-015: Hook for Stripe Payment Sheet integration

import { useState, useCallback, useRef } from 'react';
import { supabase } from '../config/supabase';
import { Platform } from 'react-native';
import { useStripe, initStripe } from '@stripe/stripe-react-native';

interface PaymentSheetOptions {
  amount: number; // Amount in cents (for display only)
  isRenewal?: boolean;
  userId?: string;
}

interface PaymentSheetResult {
  success: boolean;
  paymentMethodId?: string;
  error?: string;
}

export interface UsePaymentSheetReturn {
  setupPaymentSheet: (options: PaymentSheetOptions) => Promise<void>;
  presentSheet: () => Promise<PaymentSheetResult>;
  loading: boolean;
  error: string | null;
  resetError: () => void;
}

/**
 * Hook for managing Stripe Payment Sheet
 * 
 * Usage:
 * ```tsx
 * const { setupPaymentSheet, presentSheet, loading, error } = usePaymentSheet();
 * 
 * // When user clicks "Subscribe"
 * await setupPaymentSheet({ amount: dynamicPriceCents, isRenewal: false });
 * const result = await presentSheet();
 * if (result.success) {
 *   // Call create-subscription-from-payment-method with result.paymentMethodId
 * }
 * ```
 */
export function usePaymentSheet(): UsePaymentSheetReturn {
  const { retrieveSetupIntent } = useStripe();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const paymentSheetReadyRef = useRef(false);
  const setupIntentClientSecretRef = useRef<string | null>(null);

  const setupPaymentSheet = useCallback(
    async (options: PaymentSheetOptions): Promise<void> => {
      setLoading(true);
      setError(null);
      paymentSheetReadyRef.current = false;
      setupIntentClientSecretRef.current = null;

      try {
        // Get current session
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();

        if (sessionError || !session) {
          throw new Error('Not authenticated');
        }

        const accessToken = session.access_token;
        const userId = options.userId || session.user.id;

        // Call edge function to create SetupIntent.
        // Using supabase.functions.invoke avoids physical-device env URL drift.
        const { data, error: invokeError } = await supabase.functions.invoke(
          'create-payment-setup-intent',
          {
            body: {
              user_id: userId,
              for_renewal: options.isRenewal || false,
            },
            headers: {
              Authorization: `Bearer ${accessToken}`,
            },
          }
        );

        if (invokeError) {
          const message =
            (invokeError as any)?.context?.statusText || invokeError.message || 'Failed to create payment setup';
          throw new Error(message);
        }

        if (!data?.client_secret || !data?.customer_id || !data?.ephemeral_key_secret) {
          throw new Error('Payment setup response missing required Stripe fields');
        }

        // Runtime publishable key alignment prevents physical-device key mismatch
        // between app bundle env and edge-function Stripe mode.
        if (typeof data.publishable_key === 'string' && data.publishable_key.startsWith('pk_')) {
          await initStripe({
            publishableKey: data.publishable_key,
            merchantIdentifier: 'merchant.com.p2pkidsmarketplace',
            urlScheme: 'p2pkidsmarketplace',
          });
        }

        setupIntentClientSecretRef.current = data.client_secret;

        const { initPaymentSheet } = require('@stripe/stripe-react-native');

        // Initialize Payment Sheet with SetupIntent
        const { error: initError } = await initPaymentSheet({
          merchantDisplayName: 'Kids P2P Marketplace',
          customerId: data.customer_id,
          customerEphemeralKeySecret: data.ephemeral_key_secret,
          setupIntentClientSecret: data.client_secret,
          allowsDelayedPaymentMethods: false,
          returnURL: 'p2pkidsmarketplace://stripe-redirect',
          appearance: {
            colors: {
              primary: '#007AFF',
              background: '#FFFFFF',
            },
          },
          // Keep wallet methods platform-specific to avoid device-specific rendering issues.
          ...(Platform.OS === 'ios'
            ? {
                applePay: {
                  merchantCountryCode: 'US',
                },
              }
            : {}),
          ...(Platform.OS === 'android'
            ? {
                googlePay: {
                  merchantCountryCode: 'US',
                  testEnv: __DEV__,
                  currencyCode: 'USD',
                },
              }
            : {}),
        });

        if (initError) {
          throw new Error(initError.message || 'Failed to initialize payment sheet');
        }

        paymentSheetReadyRef.current = true;
        console.log('[usePaymentSheet] Payment sheet initialized successfully');
      } catch (err: any) {
        console.error('[usePaymentSheet] Setup error:', err);
        setError(err.message || 'Failed to setup payment');
        paymentSheetReadyRef.current = false;
        setupIntentClientSecretRef.current = null;
        throw err;
      } finally {
        setLoading(false);
      }
    },
    []
  );

  const presentSheet = useCallback(async (): Promise<PaymentSheetResult> => {
    if (!paymentSheetReadyRef.current) {
      const errorMsg = 'Payment sheet not initialized. Call setupPaymentSheet first.';
      setError(errorMsg);
      return { success: false, error: errorMsg };
    }

    setLoading(true);
    setError(null);

    try {
      const { presentPaymentSheet } = require('@stripe/stripe-react-native');
      const { error: presentError } = await presentPaymentSheet();

      if (presentError) {
        // User cancelled
        if (presentError.code === 'Canceled') {
          console.log('[usePaymentSheet] User cancelled payment sheet');
          return { success: false, error: 'Payment cancelled' };
        }

        // Other error
        throw new Error(presentError.message || 'Payment failed');
      }

      if (!setupIntentClientSecretRef.current) {
        throw new Error('Setup intent client secret missing after payment sheet completion');
      }

      const { setupIntent, error: retrieveError } = await retrieveSetupIntent(
        setupIntentClientSecretRef.current
      );

      if (retrieveError) {
        throw new Error(retrieveError.message || 'Failed to verify payment method');
      }

      const paymentMethodId = setupIntent?.paymentMethodId;

      if (!paymentMethodId) {
        throw new Error('Payment method was not returned from Stripe');
      }

      console.log('[usePaymentSheet] Payment sheet completed successfully');

      return {
        success: true,
        paymentMethodId,
      };
    } catch (err: any) {
      console.error('[usePaymentSheet] Present error:', err);
      const errorMessage = err.message || 'Payment failed';
      setError(errorMessage);
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
      paymentSheetReadyRef.current = false;
      setupIntentClientSecretRef.current = null;
    }
  }, [retrieveSetupIntent]);

  const resetError = useCallback(() => {
    setError(null);
  }, []);

  return {
    setupPaymentSheet,
    presentSheet,
    loading,
    error,
    resetError,
  };
}

// File: p2p-kids-marketplace/src/components/subscription/SubscribeButton.tsx
// MODULE-11 SUB-015: Subscribe button with integrated payment flow

import React, { useState } from 'react';
import {
  View,
  Text,
  ActivityIndicator,
  StyleSheet,
  Pressable,
  Alert,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { usePaymentSheet } from '../../hooks/usePaymentSheet';
import { supabase } from '../../config/supabase';
import type { RootStackParamList } from '@/navigation/types';

interface SubscribeButtonProps {
  /** Whether this is a renewal from grace_period/expired */
  isRenewal?: boolean;
  /** Price in cents, sourced from admin config/tier settings */
  priceCents: number;
  /** Custom label */
  label?: string;
  /** Callback after successful subscription creation */
  onSuccess?: () => void;
  /** Trial days for copy text when not renewal */
  trialDays?: number;
  /** Test ID for Maestro */
  testID?: string;
}

type NavigationProp = NativeStackNavigationProp<RootStackParamList>;

function formatPriceLabel(priceCents: number): string {
  return `$${(priceCents / 100).toFixed(2)}/month`;
}

export function SubscribeButton({
  isRenewal = false,
  priceCents,
  label,
  onSuccess,
  trialDays = 30,
  testID = 'subscribe-button',
}: SubscribeButtonProps) {
  const navigation = useNavigation<NavigationProp>();
  const { setupPaymentSheet, presentSheet, loading, error, resetError } = usePaymentSheet();
  const [processing, setProcessing] = useState(false);

  const buttonLabel =
    label ||
    (isRenewal ? 'Re-subscribe Now' : 'Subscribe to Kids Club+');
  const priceLabel = formatPriceLabel(priceCents);

  const handleSubscribe = async () => {
    try {
      setProcessing(true);
      resetError();

      // Step 1: Setup Payment Sheet
      console.log('[SubscribeButton] Setting up payment sheet...');
      await setupPaymentSheet({
        amount: priceCents,
        isRenewal,
      });

      // Step 2: Present Payment Sheet
      console.log('[SubscribeButton] Presenting payment sheet...');
      const result = await presentSheet();

      if (!result.success) {
        if (result.error === 'Payment cancelled') {
          // User cancelled - don't show error
          console.log('[SubscribeButton] User cancelled payment');
          return;
        }

        throw new Error(result.error || 'Payment failed');
      }

      // Step 3: Create subscription with payment method
      console.log('[SubscribeButton] Payment method collected, creating subscription...');

      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();

      if (sessionError || !session) {
        throw new Error('Not authenticated');
      }

      // Note: We need to get the actual payment_method_id from the SetupIntent
      // For now, we'll let the webhook handle the subscription creation
      // Alternative: retrieve SetupIntent and get payment_method from it

      const { data: subscriptionData, error: createSubError } = await supabase.functions.invoke(
        'create-subscription-from-payment-method',
        {
          body: {
            user_id: session.user.id,
            payment_method_id: result.paymentMethodId,
            is_renewal: isRenewal,
          },
          headers: {
            Authorization: `Bearer ${session.access_token}`,
          },
        }
      );

      if (createSubError) {
        throw new Error(createSubError.message || 'Failed to create subscription');
      }

      console.log('[SubscribeButton] Subscription created:', subscriptionData);

      // Show success message
      Alert.alert(
        'Success!',
        isRenewal
          ? 'Welcome back to Kids Club+! Your Swap Points have been unfrozen.'
          : 'Welcome to Kids Club+! Your 30-day free trial has started.',
        [
          {
            text: 'OK',
            onPress: () => {
              if (onSuccess) {
                onSuccess();
              } else {
                // Navigate to subscription status screen
                navigation.navigate('SubscriptionStatus');
              }
            },
          },
        ]
      );
    } catch (err: any) {
      console.error('[SubscribeButton] Error:', err);

      Alert.alert(
        'Payment Error',
        err.message || 'Unable to process payment. Please try again.',
        [{ text: 'OK' }]
      );
    } finally {
      setProcessing(false);
    }
  };

  const isLoading = loading || processing;

  return (
    <View style={styles.container}>
      <Pressable
        style={[styles.button, isLoading && styles.buttonDisabled]}
        onPress={handleSubscribe}
        disabled={isLoading}
        testID={testID}
      >
        {isLoading ? (
          <ActivityIndicator color="#FFFFFF" testID={`${testID}-loading`} />
        ) : (
          <Text style={styles.buttonText} testID={`${testID}-label`}>
            {buttonLabel}
          </Text>
        )}
      </Pressable>

      {error && (
        <Text style={styles.errorText} testID={`${testID}-error`}>
          {error}
        </Text>
      )}

      <Text style={styles.disclaimer} testID={`${testID}-disclaimer`}>
        {isRenewal
          ? `Your card will be charged ${priceLabel}. Cancel anytime.`
          : `${priceLabel} after ${trialDays}-day free trial. Cancel anytime.`}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  button: {
    backgroundColor: '#007AFF',
    paddingVertical: 16,
    paddingHorizontal: 24,
    borderRadius: 12,
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: 56,
  },
  buttonDisabled: {
    backgroundColor: '#999999',
  },
  buttonText: {
    color: '#FFFFFF',
    fontSize: 17,
    fontWeight: '600',
  },
  errorText: {
    color: '#FF3B30',
    fontSize: 14,
    marginTop: 8,
    textAlign: 'center',
  },
  disclaimer: {
    color: '#8E8E93',
    fontSize: 12,
    marginTop: 8,
    textAlign: 'center',
  },
});

